using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

namespace XFramework.XConfig.Luban.Editor
{
    /// <summary>
    /// 接入代码写盘结果。
    /// </summary>
    internal sealed class LubanIntegrationWriteResult
    {
        internal List<string> Written { get; } = new();
        internal List<string> Deleted { get; } = new();
        internal List<string> Unchanged { get; } = new();
    }

    /// <summary>
    /// 把行接口实现/适配器写到 <c>IntegrationOutputDir</c>：auto-generated 头、内容未变不写、
    /// 拒绝覆盖非生成文件、按 manifest 清理旧文件。
    /// <para><b>写盘分三段：暂存 → 提交 → 回滚。</b>① 先把全部新内容（含 manifest）写进输出目录下的
    /// 隐藏暂存目录（Unity 不导入 `.` 开头的目录），任一失败即清掉暂存、目标一个字节都没动；
    /// ② 提交时**旧文件先移成备份、新文件再移入目标**（不再「删旧 → move」，那中间有一个零副本窗口），
    /// manifest 最后提交；③ 任一步失败按逆序回滚（恢复备份、删除新建、清暂存）并抛带可操作消息的
    /// <see cref="LubanGenerationException"/>。</para>
    /// <para><b>边界</b>：回滚只覆盖**进程内可捕获的失败**；进程崩溃 / 断电不做自动恢复，备份会留在
    /// 隐藏暂存目录里，可人工恢复。不宣称崩溃级原子。</para>
    /// </summary>
    internal static class LubanIntegrationWriter
    {
        internal const string ManifestFileName = ".luban-integration-manifest";
        private const string ManifestHeader = "xfw-luban-integration/1";

        private static readonly UTF8Encoding Utf8NoBom = new UTF8Encoding(false);

        internal static LubanIntegrationWriteResult Write(
            string integrationDir,
            IReadOnlyDictionary<string, string> files,
            IReadOnlyList<string> tableLines)
        {
            if (string.IsNullOrWhiteSpace(integrationDir))
            {
                throw new ArgumentException("接入代码输出目录为空。", nameof(integrationDir));
            }

            string root = Path.GetFullPath(integrationDir);
            Directory.CreateDirectory(root);

            var previous = ReadManifest(root);
            var result = new LubanIntegrationWriteResult();
            var currentFiles = new HashSet<string>(StringComparer.Ordinal);
            var toWrite = new List<(string Relative, string FullPath, string Content)>();
            var toDelete = new List<(string Relative, string FullPath)>();

            // 第一遍只做校验：归一化、路径包含、覆盖保护、同名目录与归一化重名。
            // 任何拒绝都必须发生在写盘之前，否则会留下半套新文件 + 旧 manifest。
            foreach (var pair in files)
            {
                string relative = NormalizeRelative(pair.Key);
                if (!currentFiles.Add(relative))
                {
                    throw new LubanGenerationException(
                        "接入代码文件路径归一化后重复：" + relative);
                }

                string fullPath = ResolveUnder(root, relative);

                if (Directory.Exists(fullPath))
                {
                    throw new LubanGenerationException(
                        "目标路径已存在同名目录，无法写入文件：" + fullPath + "（请先移走该目录后重试）");
                }

                if (File.Exists(fullPath))
                {
                    string existing = File.ReadAllText(fullPath, Encoding.UTF8);
                    if (string.Equals(existing, pair.Value, StringComparison.Ordinal))
                    {
                        result.Unchanged.Add(relative);
                        continue;
                    }

                    if (!existing.StartsWith(LubanIntegrationEmitter.AutoGeneratedHeader, StringComparison.Ordinal))
                    {
                        throw new LubanGenerationException(
                            "拒绝覆盖非生成文件（缺少 auto-generated 头）：" + fullPath);
                    }
                }

                toWrite.Add((relative, fullPath, pair.Value));
            }

            foreach (var oldFile in previous.Files)
            {
                if (currentFiles.Contains(oldFile))
                {
                    continue;
                }

                string fullPath = ResolveUnder(root, oldFile);
                if (!File.Exists(fullPath))
                {
                    continue;
                }

                string existing = File.ReadAllText(fullPath, Encoding.UTF8);
                if (existing.StartsWith(LubanIntegrationEmitter.AutoGeneratedHeader, StringComparison.Ordinal))
                {
                    toDelete.Add((oldFile, fullPath));
                }
            }

            string manifestPath = Path.Combine(root, ManifestFileName);
            string stagingRoot = Path.Combine(root, ".xfw-luban-write-" + Guid.NewGuid().ToString("N"));

            var written = new List<WriteRecord>();
            var deleted = new List<DeleteRecord>();
            WriteRecord manifestCommit = null;
            bool keepStaging = false;

            try
            {
                Directory.CreateDirectory(stagingRoot);

                // ---------- 1) 暂存：目标一个字节都不动 ----------

                foreach (var item in toWrite)
                {
                    string staged = StagingPath(stagingRoot, "new", item.Relative);
                    Directory.CreateDirectory(Path.GetDirectoryName(staged));
                    File.WriteAllText(staged, item.Content, Utf8NoBom);
                }

                string stagedManifest = Path.Combine(stagingRoot, "new-manifest");
                File.WriteAllText(stagedManifest, BuildManifestText(files.Keys, tableLines), Utf8NoBom);

                // ---------- 2) 提交写：旧文件先移成备份 ----------

                foreach (var item in toWrite)
                {
                    string staged = StagingPath(stagingRoot, "new", item.Relative);
                    var record = new WriteRecord { Target = item.FullPath };

                    string targetDirectory = Path.GetDirectoryName(item.FullPath);
                    if (!string.IsNullOrEmpty(targetDirectory))
                    {
                        Directory.CreateDirectory(targetDirectory);
                    }

                    if (File.Exists(item.FullPath))
                    {
                        record.Backup = StagingPath(stagingRoot, "old", item.Relative);
                        Directory.CreateDirectory(Path.GetDirectoryName(record.Backup));
                        File.Move(item.FullPath, record.Backup);
                    }

                    // 先登记再移入：第二步失败时回滚也能看见「备份已移走」
                    written.Add(record);
                    File.Move(staged, item.FullPath);
                    result.Written.Add(item.Relative);
                }

                // ---------- 3) 提交删：stale 文件也先移成备份 ----------

                foreach (var item in toDelete)
                {
                    var record = new DeleteRecord
                    {
                        Target = item.FullPath,
                        MetaTarget = item.FullPath + ".meta",
                    };
                    record.Backup = StagingPath(stagingRoot, "deleted", item.Relative);
                    Directory.CreateDirectory(Path.GetDirectoryName(record.Backup));

                    deleted.Add(record);
                    File.Move(item.FullPath, record.Backup);

                    if (File.Exists(record.MetaTarget))
                    {
                        record.MetaBackup = record.Backup + ".meta";
                        File.Move(record.MetaTarget, record.MetaBackup);
                    }

                    result.Deleted.Add(item.Relative);
                }

                // ---------- 4) manifest 最后提交 ----------

                manifestCommit = new WriteRecord { Target = manifestPath };
                if (File.Exists(manifestPath))
                {
                    manifestCommit.Backup = Path.Combine(stagingRoot, "old-manifest");
                    File.Move(manifestPath, manifestCommit.Backup);
                }

                File.Move(stagedManifest, manifestPath);
            }
            catch (Exception error)
            {
                var rollbackFailures = Rollback(written, deleted, manifestCommit);
                keepStaging = rollbackFailures.Count > 0;
                throw new LubanGenerationException(
                    BuildFailureMessage(stagingRoot, error, rollbackFailures), error);
            }
            finally
            {
                if (!keepStaging)
                {
                    try
                    {
                        if (Directory.Exists(stagingRoot))
                        {
                            Directory.Delete(stagingRoot, true);
                        }
                    }
                    catch
                    {
                        // 清理失败留下的隐藏目录无害；不能让它覆盖原始异常。
                    }
                }
            }

            return result;
        }

        internal static ManifestData ReadManifest(string integrationDir)
        {
            var data = new ManifestData();
            string path = Path.Combine(integrationDir, ManifestFileName);
            if (!File.Exists(path))
            {
                return data;
            }

            string[] lines = File.ReadAllLines(path, Encoding.UTF8);
            if (lines.Length == 0 || lines[0] != ManifestHeader)
            {
                throw new LubanGenerationException(
                    "无法识别的接入代码 manifest：" + path + "（请删除后重试）。");
            }

            for (int i = 1; i < lines.Length; i++)
            {
                string line = lines[i];
                if (line.StartsWith("file:", StringComparison.Ordinal))
                {
                    data.Files.Add(NormalizeRelative(line.Substring(5)));
                }
                else if (line.StartsWith("table:", StringComparison.Ordinal))
                {
                    data.Tables.Add(line.Substring(6));
                }
            }

            return data;
        }

        #region 事务辅助

        private sealed class WriteRecord
        {
            internal string Target;
            internal string Backup;
        }

        private sealed class DeleteRecord
        {
            internal string Target;
            internal string MetaTarget;
            internal string Backup;
            internal string MetaBackup;
        }

        private static string BuildManifestText(
            IEnumerable<string> files,
            IReadOnlyList<string> tableLines)
        {
            var builder = new StringBuilder();
            builder.Append(ManifestHeader).Append('\n');

            var sorted = new List<string>(files);
            sorted.Sort(StringComparer.Ordinal);
            foreach (var file in sorted)
            {
                builder.Append("file:").Append(NormalizeRelative(file)).Append('\n');
            }

            for (int i = 0; i < tableLines.Count; i++)
            {
                builder.Append("table:").Append(tableLines[i]).Append('\n');
            }

            return builder.ToString();
        }

        private static string StagingPath(string stagingRoot, string kind, string relative)
            => Path.Combine(stagingRoot, kind, relative.Replace('/', Path.DirectorySeparatorChar));

        /// <summary>逆序回滚：manifest → 删除项（逆序）→ 写入项（逆序）。返回失败清单。</summary>
        private static List<string> Rollback(
            List<WriteRecord> written,
            List<DeleteRecord> deleted,
            WriteRecord manifestCommit)
        {
            var failures = new List<string>();

            if (manifestCommit != null)
            {
                RollbackWrite(manifestCommit, failures);
            }

            for (int i = deleted.Count - 1; i >= 0; i--)
            {
                RollbackDelete(deleted[i], failures);
            }

            for (int i = written.Count - 1; i >= 0; i--)
            {
                RollbackWrite(written[i], failures);
            }

            return failures;
        }

        private static void RollbackWrite(WriteRecord record, List<string> failures)
        {
            try
            {
                if (File.Exists(record.Target))
                {
                    File.Delete(record.Target);
                }

                if (record.Backup != null && File.Exists(record.Backup))
                {
                    File.Move(record.Backup, record.Target);
                }
            }
            catch (Exception error)
            {
                failures.Add(record.Target + "：" + error.Message);
            }
        }

        private static void RollbackDelete(DeleteRecord record, List<string> failures)
        {
            try
            {
                if (record.MetaBackup != null && File.Exists(record.MetaBackup))
                {
                    File.Move(record.MetaBackup, record.MetaTarget);
                }

                if (record.Backup != null && File.Exists(record.Backup))
                {
                    File.Move(record.Backup, record.Target);
                }
            }
            catch (Exception error)
            {
                failures.Add(record.Target + "：" + error.Message);
            }
        }

        private static string BuildFailureMessage(
            string stagingRoot,
            Exception error,
            List<string> rollbackFailures)
        {
            var builder = new StringBuilder();
            builder.Append("接入代码写盘失败：").Append(error.Message).Append('\n');

            if (rollbackFailures.Count == 0)
            {
                builder.Append("本次写入已全部回滚（新文件已删除、被替换 / 删除的文件已恢复、manifest 未变）。\n");
                builder.Append("常见原因：目标路径被占用 / 只读、同名目录挡路、磁盘空间或权限不足。处理后重试即可。");
            }
            else
            {
                builder.Append("**回滚未完全成功**（").Append(rollbackFailures.Count).Append(" 处）：\n");
                foreach (var failure in rollbackFailures)
                {
                    builder.Append("  - ").Append(failure).Append('\n');
                }

                builder.Append("备份保留在：").Append(stagingRoot).Append("（请人工恢复后删除该目录）。");
            }

            return builder.ToString();
        }

        #endregion

        private static string NormalizeRelative(string relative)
        {
            string normalized = relative.Replace('\\', '/').Trim();
            if (normalized.StartsWith("./", StringComparison.Ordinal))
            {
                normalized = normalized.Substring(2);
            }

            if (normalized.StartsWith("/", StringComparison.Ordinal) ||
                normalized.IndexOf(':') >= 0)
            {
                throw new LubanGenerationException("接入代码文件路径必须是相对路径：" + relative);
            }

            foreach (var segment in normalized.Split('/'))
            {
                if (segment == "..")
                {
                    throw new LubanGenerationException("接入代码文件路径不能包含 '..'：" + relative);
                }
            }

            return normalized;
        }

        private static string ResolveUnder(string root, string relative)
        {
            string fullPath = Path.GetFullPath(
                Path.Combine(root, relative.Replace('/', Path.DirectorySeparatorChar)));
            string prefix = root.TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar;
            StringComparison comparison = Path.DirectorySeparatorChar == '\\'
                ? StringComparison.OrdinalIgnoreCase
                : StringComparison.Ordinal;

            if (!fullPath.StartsWith(prefix, comparison))
            {
                throw new LubanGenerationException("接入代码文件路径越出输出目录：" + relative);
            }

            return fullPath;
        }

        internal sealed class ManifestData
        {
            internal HashSet<string> Files { get; } = new(StringComparer.Ordinal);
            internal List<string> Tables { get; } = new();
        }
    }
}
